<template>
  <SubHeader
    name="idea_board"
    :label="$t('idea_board')"
    :onSearch="false"
    :show_expiry_alert="false"
  />
  <q-page class="max-w-[900px] mx-auto px-4 py-6">
    <!-- Tabs: Ideas / Moderation (moderator orgs only) -->
    <q-tabs
      v-if="ideasStore.hasModerationAccess"
      v-model="activeTab"
      dense
      class="mb-6 border-b border-border"
      active-color="primary"
      indicator-color="primary"
      align="left"
      narrow-indicator
    >
      <q-tab name="ideas" :label="$t('ideas')" no-caps />
      <q-tab name="moderation" no-caps>
        <div class="flex items-center gap-2">
          {{ $t('moderation') }}
          <q-badge
            v-if="pendingModerationCount > 0"
            color="red"
            :label="pendingModerationCount"
            rounded
          />
        </div>
      </q-tab>
    </q-tabs>

    <!-- Moderation Tab Content -->
    <IdeaModerationTab
      v-if="ideasStore.hasModerationAccess && activeTab === 'moderation'"
      @show-idea="onShowIdea"
    />

    <!-- Channel chips -->
    <div v-show="activeTab === 'ideas'" class="flex gap-2 mb-6 items-center flex-wrap">
      <q-chip
        flat
        :color="selectedChannel === null ? 'primary' : 'grey-3'"
        :text-color="selectedChannel === null ? 'white' : 'grey-8'"
        clickable
        dense
        class="filter-chip"
        @click="onChannelSelect(null)"
      >
        {{ $t('all') }}
      </q-chip>
      <q-chip
        v-for="ch in channelOptions"
        :key="ch.value"
        flat
        :color="selectedChannel === ch.value ? 'primary' : 'grey-3'"
        :text-color="selectedChannel === ch.value ? 'white' : 'grey-8'"
        clickable
        dense
        class="filter-chip"
        @click="onChannelSelect(ch.value)"
      >
        {{ $t(ch.label) }}
      </q-chip>
    </div>

    <!-- Search + New Idea row -->
    <div v-show="activeTab === 'ideas'" class="flex gap-3 mb-3 items-center">
      <q-input
        v-model="searchText"
        :placeholder="$t('search') + '...'"
        dense
        outlined
        clearable
        debounce="400"
        class="flex-1"
        @update:model-value="onFilterChange"
      >
        <template #prepend>
          <Icon icon="mdi:magnify" class="size-5 text-muted-foreground" />
        </template>
      </q-input>
      <q-btn color="primary" no-caps @click="showNewIdeaDialog = true">
        <Icon icon="mdi:plus" class="size-5 mr-1" />
        {{ $t('new_idea') }}
      </q-btn>
    </div>

    <!-- Filter controls row -->
    <div v-show="activeTab === 'ideas'" class="flex gap-3 mb-6 items-center flex-wrap">
      <q-select
        v-model="selectedCategory"
        :options="categoryOptions"
        :option-label="(opt: { label: string }) => $t(opt.label)"
        :label="$t('idea_category')"
        emit-value
        map-options
        clearable
        dense
        outlined
        style="min-width: 150px"
        @update:model-value="onFilterChange"
      />
      <q-select
        v-model="selectedStatus"
        :options="statusOptions"
        :option-label="(opt: { label: string }) => $t(opt.label)"
        :label="$t('idea_status')"
        emit-value
        map-options
        clearable
        dense
        outlined
        style="min-width: 150px"
        @update:model-value="onFilterChange"
      />
      <div class="flex-1" />
      <span class="text-xs text-muted-foreground">{{ $t('sort_by') || 'Sort by' }}:</span>
      <q-select
        v-model="selectedSort"
        :options="sortOptions"
        :option-label="(opt: { label: string }) => $t(opt.label)"
        emit-value
        map-options
        dense
        outlined
        style="min-width: 140px"
        @update:model-value="onFilterChange"
      />
    </div>

    <!-- Loading (ideas tab) -->
    <div v-if="loading && activeTab === 'ideas'" class="text-center p-10">
      <q-spinner size="48px" color="primary" />
    </div>

    <!-- Empty state -->
    <div
      v-else-if="ideas.length === 0 && activeTab === 'ideas'"
      class="flex flex-col items-center text-center p-10 text-muted-foreground"
    >
      <Icon icon="mdi:lightbulb-outline" class="size-16 mb-4" />
      <div class="text-h6">{{ $t('no_ideas_yet') }}</div>
      <div class="text-body2 mt-2">{{ $t('be_first_to_share') }}</div>
    </div>

    <!-- Ideas list -->
    <div v-else-if="activeTab === 'ideas'" class="flex flex-col gap-4">
      <IdeaCard
        v-for="idea in ideas"
        :key="idea.id"
        :idea="idea"
        :current-user-id="currentUserId"
        :user-vote="ideasStore.getIdeaVote(idea.id)"
        :is-moderator="ideasStore.hasModerationAccess"
        :show-comments="!!expandedComments[idea.id]"
        :comments-loading="!!commentsLoading[idea.id]"
        :comments="ideasStore.comments[idea.id] || []"
        :assets="ideasStore.assets[idea.id] || []"
        :comment-count="getCommentCount(idea.id)"
        :get-comment-vote="(commentId: string) => ideasStore.getCommentVote(commentId)"
        @vote-idea="onVoteIdea"
        @toggle-comments="onToggleComments"
        @delete-comment="onDeleteComment"
        @vote-comment="onVoteComment"
        @edit-idea="onEditIdea"
        @delete-idea="onDeleteIdea"
        @update-status="onUpdateStatus"
      />
    </div>

    <!-- Pagination -->
    <div
      v-if="pagination.total_pages > 1 && activeTab === 'ideas'"
      class="flex justify-center mt-6"
    >
      <q-pagination
        v-model="currentPage"
        :max="pagination.total_pages"
        :max-pages="7"
        direction-links
        boundary-links
        @update:model-value="onPageChange"
      />
    </div>

    <!-- New Idea Dialog -->
    <q-dialog v-model="showNewIdeaDialog" @hide="resetNewIdea">
      <q-card class="rounded-xl ideas-dialog-card" style="width: 600px; max-width: 600px">
        <!-- Header -->
        <q-card-section class="flex items-center justify-between pb-0">
          <div class="text-lg font-semibold text-foreground">{{ $t('new_idea') }}</div>
          <q-btn flat round dense @click="showNewIdeaDialog = false">
            <Icon icon="mdi:close" class="size-4 text-muted-foreground" />
          </q-btn>
        </q-card-section>

        <q-separator class="my-3" />

        <!-- Body -->
        <q-card-section class="flex flex-col gap-5 pt-0">
          <!-- Title (required) -->
          <div>
            <label class="text-sm font-medium text-foreground mb-1.5 flex items-center gap-0.5">
              {{ $t('idea_title') }}
              <span class="text-destructive">*</span>
            </label>
            <q-input
              v-model="newIdea.title"
              :placeholder="$t('idea_title_placeholder') || 'Give your idea a clear, descriptive title'"
              outlined
              dense
              :rules="[(val: string) => !!val || $t('field_required')]"
            />
          </div>

          <!-- Description (optional) -->
          <div>
            <label class="text-sm font-medium text-foreground mb-1 block">
              {{ $t('idea_description') }}
            </label>
            <div class="text-xs text-muted-foreground mb-1.5">{{ $t('idea_description_hint') || 'Optional \u2014 describe your idea in detail' }}</div>
            <q-editor
              v-model="newIdea.description"
              :toolbar="editorToolbar"
              min-height="120px"
              flat
              bordered
              content-class="idea-editor-content"
            />
            <input
              ref="fileInput"
              type="file"
              accept="image/jpeg,image/png,image/gif,image/webp"
              style="display: none"
              @change="onFileSelected"
            />
            <q-btn
              flat
              dense
              no-caps
              :loading="uploadingImage"
              class="mt-2 text-primary"
              @click="fileInput?.click()"
            >
              <Icon icon="mdi:image-plus-outline" class="size-4 mr-1" />
              {{ $t('add_image') }}
            </q-btn>
          </div>

          <!-- Category + Channel side by side -->
          <div class="flex gap-4">
            <div class="flex-1">
              <label class="text-sm font-medium text-foreground mb-1.5 flex items-center gap-0.5">
                {{ $t('idea_category') }}
                <span class="text-destructive">*</span>
              </label>
              <q-select
                v-model="newIdea.category"
                :options="categoryOptions"
                :option-label="(opt: { label: string }) => $t(opt.label)"
                emit-value
                map-options
                outlined
                dense
              />
            </div>
            <div class="flex-1">
              <label class="text-sm font-medium text-foreground mb-1.5 flex items-center gap-0.5">
                {{ $t('idea_channel') }}
                <span class="text-destructive">*</span>
              </label>
              <q-select
                v-model="newIdea.channel"
                :options="channelOptions"
                :option-label="(opt: { label: string }) => $t(opt.label)"
                emit-value
                map-options
                outlined
                dense
              />
            </div>
          </div>
        </q-card-section>

        <q-separator />

        <!-- Footer -->
        <q-card-actions class="px-6 py-4" align="right">
          <q-btn flat no-caps class="text-muted-foreground" :label="$t('cancel')" @click="showNewIdeaDialog = false" />
          <q-btn
            color="primary"
            no-caps
            :disable="!newIdea.title"
            :loading="submitting"
            @click="onSubmitIdea"
          >
            <Icon icon="mdi:send" class="size-4 mr-1.5" />
            {{ $t('submit') }}
          </q-btn>
        </q-card-actions>
      </q-card>
    </q-dialog>

    <!-- Edit Idea Dialog -->
    <q-dialog v-model="showEditIdeaDialog">
      <q-card class="rounded-xl ideas-dialog-card" style="width: 600px; max-width: 600px">
        <!-- Header -->
        <q-card-section class="flex items-center justify-between pb-0">
          <div class="text-lg font-semibold text-foreground">{{ $t('edit_idea') }}</div>
          <q-btn flat round dense @click="showEditIdeaDialog = false">
            <Icon icon="mdi:close" class="size-4 text-muted-foreground" />
          </q-btn>
        </q-card-section>

        <q-separator class="my-3" />

        <!-- Body -->
        <q-card-section class="flex flex-col gap-5 pt-0">
          <!-- Title (required) -->
          <div>
            <label class="text-sm font-medium text-foreground mb-1.5 flex items-center gap-0.5">
              {{ $t('idea_title') }}
              <span class="text-destructive">*</span>
            </label>
            <q-input
              v-model="editIdeaForm.title"
              :placeholder="$t('idea_title_placeholder') || 'Give your idea a clear, descriptive title'"
              outlined
              dense
              :rules="[(val: string) => !!val || $t('field_required')]"
            />
          </div>

          <!-- Description (optional) -->
          <div>
            <label class="text-sm font-medium text-foreground mb-1 block">
              {{ $t('idea_description') }}
            </label>
            <div class="text-xs text-muted-foreground mb-1.5">{{ $t('idea_description_hint') || 'Optional \u2014 describe your idea in detail' }}</div>
            <q-editor
              v-model="editIdeaForm.description"
              :toolbar="editorToolbar"
              min-height="120px"
              flat
              bordered
              content-class="idea-editor-content"
            />
            <input
              ref="editFileInput"
              type="file"
              accept="image/jpeg,image/png,image/gif,image/webp"
              style="display: none"
              @change="onEditFileSelected"
            />
            <q-btn
              flat
              dense
              no-caps
              :loading="uploadingImage"
              class="mt-2 text-primary"
              @click="editFileInput?.click()"
            >
              <Icon icon="mdi:image-plus-outline" class="size-4 mr-1" />
              {{ $t('add_image') }}
            </q-btn>
          </div>

          <!-- Category + Channel side by side -->
          <div class="flex gap-4">
            <div class="flex-1">
              <label class="text-sm font-medium text-foreground mb-1.5 flex items-center gap-0.5">
                {{ $t('idea_category') }}
                <span class="text-destructive">*</span>
              </label>
              <q-select
                v-model="editIdeaForm.category"
                :options="categoryOptions"
                :option-label="(opt: { label: string }) => $t(opt.label)"
                emit-value
                map-options
                outlined
                dense
              />
            </div>
            <div class="flex-1">
              <label class="text-sm font-medium text-foreground mb-1.5 flex items-center gap-0.5">
                {{ $t('idea_channel') }}
                <span class="text-destructive">*</span>
              </label>
              <q-select
                v-model="editIdeaForm.channel"
                :options="channelOptions"
                :option-label="(opt: { label: string }) => $t(opt.label)"
                emit-value
                map-options
                outlined
                dense
              />
            </div>
          </div>
        </q-card-section>

        <q-separator />

        <!-- Footer -->
        <q-card-actions class="px-6 py-4" align="right">
          <q-btn flat no-caps class="text-muted-foreground" :label="$t('cancel')" @click="showEditIdeaDialog = false" />
          <q-btn
            color="primary"
            no-caps
            :disable="!editIdeaForm.title"
            :loading="submittingEdit"
            @click="onSubmitEdit"
          >
            <Icon icon="mdi:content-save" class="size-4 mr-1.5" />
            {{ $t('save') }}
          </q-btn>
        </q-card-actions>
      </q-card>
    </q-dialog>

    <!-- Delete Confirmation Dialog -->
    <q-dialog v-model="showDeleteDialog">
      <q-card class="rounded-xl">
        <q-card-section class="flex items-center justify-between">
          <div class="text-h6">{{ $t('confirm_delete') }}</div>
          <q-btn flat round dense @click="showDeleteDialog = false">
            <Icon icon="mdi:close" class="size-4" />
          </q-btn>
        </q-card-section>
        <q-card-section>
          <div>{{ $t('delete_idea_confirm') }}</div>
        </q-card-section>
        <q-card-actions align="right">
          <q-btn flat :label="$t('cancel')" @click="showDeleteDialog = false" />
          <q-btn color="negative" :label="$t('delete')" @click="onConfirmDelete" />
        </q-card-actions>
      </q-card>
    </q-dialog>
  </q-page>
</template>

<script lang="ts">
import { defineComponent, ref, reactive, onMounted, computed } from 'vue';
import { storeToRefs } from 'pinia';
import { Icon } from '@iconify/vue';
import { useIdeasStore } from 'src/store/main';
import { useUserStore } from 'src/store/main';
import type { Idea, IdeaCategory, IdeaChannel, IdeaStatus, VoteDirection } from 'src/types/api/ideas';
import { IDEA_CATEGORIES, IDEA_CHANNELS, IDEA_STATUSES } from 'src/types/api/ideas';
import IdeaCard from './IdeaCard.vue';
import IdeaModerationTab from './IdeaModerationTab.vue';
import SubHeader from 'src/pages/Settings/Components/Sub-Header.vue';
import { DocBitsNotification } from 'src/components/DocBitsNotification';

const ALLOWED_INLINE_IMAGE_TYPES = ['image/jpeg', 'image/png', 'image/gif', 'image/webp'];
const ALLOWED_INLINE_IMAGE_LABEL = 'JPG, PNG, GIF, WebP';

function validateInlineImage(file: File): { valid: boolean; error?: string } {
  if (ALLOWED_INLINE_IMAGE_TYPES.includes(file.type)) {
    return { valid: true };
  }
  return {
    valid: false,
    error: `That image type isn't supported. Please use ${ALLOWED_INLINE_IMAGE_LABEL}.`,
  };
}

export default defineComponent({
  name: 'IdeaBoard',
  components: { Icon, IdeaCard, IdeaModerationTab, SubHeader },

  setup() {
    const ideasStore = useIdeasStore();
    const userStore = useUserStore();
    const { ideas, loading, pagination } = storeToRefs(ideasStore);

    const currentUserId = Number(userStore.getUserId()) || 0;
    const activeTab = ref('ideas');

    const showNewIdeaDialog = ref(false);
    const showEditIdeaDialog = ref(false);
    const showDeleteDialog = ref(false);
    const submitting = ref(false);
    const submittingEdit = ref(false);
    const currentPage = ref(1);
    const fileInput = ref<HTMLInputElement | null>(null);
    const editFileInput = ref<HTMLInputElement | null>(null);
    const uploadingImage = ref(false);
    const editIdeaId = ref('');
    const deleteIdeaId = ref('');
    const expandedComments = reactive<Record<string, boolean>>({});
    const commentsLoading = reactive<Record<string, boolean>>({});

    const editorToolbar = [
      ['bold', 'italic', 'underline', 'strike'],
      ['unordered', 'ordered'],
      ['link'],
    ];

    const selectedCategory = ref<IdeaCategory | null>(null);
    const selectedChannel = ref<IdeaChannel | null>(null);
    const selectedStatus = ref<IdeaStatus | null>(null);
    const searchText = ref('');
    const selectedSort = ref('newest');

    const newIdea = ref({
      title: '',
      description: '',
      category: 'feature' as IdeaCategory,
      channel: 'general' as IdeaChannel,
    });

    function resetNewIdea() {
      newIdea.value = {
        title: '',
        description: '',
        category: 'feature',
        channel: 'general',
      };
    }

    const editIdeaForm = ref({
      title: '',
      description: '',
      category: 'feature' as IdeaCategory,
      channel: 'general' as IdeaChannel,
    });

    const categoryOptions = IDEA_CATEGORIES;
    const channelOptions = IDEA_CHANNELS;
    const statusOptions = IDEA_STATUSES;

    const sortOptions = [
      { label: 'newest', value: 'newest' },
      { label: 'hot', value: 'hot' },
      { label: 'top_rated', value: 'top_rated' },
    ];

    function onChannelSelect(channel: IdeaChannel | null) {
      selectedChannel.value = channel;
      ideasStore.setFilter('channel', channel);
      currentPage.value = 1;
      ideasStore.loadIdeas(1);
    }

    function onFilterChange() {
      ideasStore.setFilter('category', selectedCategory.value);
      ideasStore.setFilter('channel', selectedChannel.value);
      ideasStore.setFilter('status', selectedStatus.value);
      ideasStore.setFilter('search', searchText.value);
      ideasStore.setFilter('sort', selectedSort.value);
      currentPage.value = 1;
      ideasStore.loadIdeas(1);
    }

    function onPageChange(page: number) {
      ideasStore.loadIdeas(page);
    }

    function readFileAsDataUrl(file: File): Promise<string> {
      return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result as string);
        reader.onerror = () => reject(reader.error);
        reader.readAsDataURL(file);
      });
    }

    async function onFileSelected(event: Event) {
      const target = event.target as HTMLInputElement;
      const file = target.files?.[0];
      if (!file) return;

      const { valid, error } = validateInlineImage(file);
      if (!valid) {
        DocBitsNotification.error(error as string);
        if (fileInput.value) fileInput.value.value = '';
        return;
      }

      uploadingImage.value = true;
      try {
        const dataUrl = await readFileAsDataUrl(file);
        newIdea.value.description += `<img src="${dataUrl}" style="max-width:100%;border-radius:8px;margin:8px 0" />`;
      } catch (error) {
        console.error('Failed to read image:', error);
        DocBitsNotification.error('Failed to load image.');
      } finally {
        uploadingImage.value = false;
        if (fileInput.value) fileInput.value.value = '';
      }
    }

    async function onEditFileSelected(event: Event) {
      const target = event.target as HTMLInputElement;
      const file = target.files?.[0];
      if (!file) return;

      const { valid, error } = validateInlineImage(file);
      if (!valid) {
        DocBitsNotification.error(error as string);
        if (editFileInput.value) editFileInput.value.value = '';
        return;
      }

      uploadingImage.value = true;
      try {
        const dataUrl = await readFileAsDataUrl(file);
        editIdeaForm.value.description += `<img src="${dataUrl}" style="max-width:100%;border-radius:8px;margin:8px 0" />`;
      } catch (error) {
        console.error('Failed to read image:', error);
        DocBitsNotification.error('Failed to load image.');
      } finally {
        uploadingImage.value = false;
        if (editFileInput.value) editFileInput.value.value = '';
      }
    }

    function onEditIdea(ideaId: string) {
      const idea = ideas.value.find((i: Idea) => i.id === ideaId);
      if (!idea) return;
      editIdeaId.value = idea.id;
      editIdeaForm.value = {
        title: idea.title,
        description: idea.description || '',
        category: idea.category,
        channel: idea.channel || 'general',
      };
      showEditIdeaDialog.value = true;
    }

    async function onSubmitEdit() {
      if (!editIdeaForm.value.title) return;
      submittingEdit.value = true;
      let success = false;
      try {
        await ideasStore.updateIdea(editIdeaId.value, {
          title: editIdeaForm.value.title,
          description: editIdeaForm.value.description || undefined,
          category: editIdeaForm.value.category,
          channel: editIdeaForm.value.channel,
        });
        success = true;
      } catch (error) {
        console.error('Failed to update idea:', error);
      } finally {
        submittingEdit.value = false;
        if (success) {
          showEditIdeaDialog.value = false;
        }
      }
    }

    function onDeleteIdea(ideaId: string) {
      deleteIdeaId.value = ideaId;
      showDeleteDialog.value = true;
    }

    async function onConfirmDelete() {
      try {
        await ideasStore.deleteIdea(deleteIdeaId.value);
      } catch (error) {
        console.error('Failed to delete idea:', error);
      } finally {
        showDeleteDialog.value = false;
      }
    }

    function getCommentCount(ideaId: string): number {
      const loaded = ideasStore.comments[ideaId];
      if (loaded && loaded.length > 0) return loaded.length;
      const idea = ideas.value.find((i: Idea) => i.id === ideaId);
      return idea?.comment_count ?? 0;
    }

    async function onToggleComments(ideaId: string) {
      if (expandedComments[ideaId]) {
        expandedComments[ideaId] = false;
        return;
      }
      expandedComments[ideaId] = true;
      commentsLoading[ideaId] = true;
      try {
        await Promise.all([
          ideasStore.loadComments(ideaId),
          ideasStore.loadAssets(ideaId),
        ]);
      } finally {
        commentsLoading[ideaId] = false;
      }
    }

    async function onDeleteComment(ideaId: string, commentId: string) {
      try {
        await ideasStore.removeComment(ideaId, commentId);
      } catch (error) {
        console.error('Failed to delete comment:', error);
      }
    }

    async function onVoteIdea(ideaId: string, direction: VoteDirection) {
      await ideasStore.voteOnIdea(ideaId, direction);
    }

    async function onVoteComment(ideaId: string, commentId: string, direction: VoteDirection) {
      await ideasStore.voteOnComment(ideaId, commentId, direction);
    }

    async function onUpdateStatus(ideaId: string, status: IdeaStatus) {
      try { await ideasStore.updateStatus(ideaId, status); } catch { /* notified in store */ }
    }

    function onShowIdea(ideaId: string) {
      activeTab.value = 'ideas';
      expandedComments[ideaId] = true;
      commentsLoading[ideaId] = true;
      Promise.all([
        ideasStore.loadComments(ideaId),
        ideasStore.loadAssets(ideaId),
      ]).finally(() => {
        commentsLoading[ideaId] = false;
      });
    }

    async function onSubmitIdea() {
      if (!newIdea.value.title) return;
      submitting.value = true;
      let success = false;
      try {
        await ideasStore.createIdea({
          title: newIdea.value.title,
          description: newIdea.value.description || undefined,
          category: newIdea.value.category,
          channel: newIdea.value.channel,
        });
        success = true;
      } catch (error) {
        console.error('Failed to submit idea:', error);
      } finally {
        submitting.value = false;
        if (success) {
          showNewIdeaDialog.value = false;
        }
      }
    }

    onMounted(async () => {
      ideasStore.loadIdeas(1);
      await ideasStore.checkModerationAccess();
      if (ideasStore.hasModerationAccess) {
        ideasStore.loadPendingComments();
        ideasStore.loadPendingIdeas();
      }
    });

    const pendingModerationCount = computed(
      () => ideasStore.pendingComments.length + ideasStore.pendingIdeas.length,
    );

    return {
      ideas,
      loading,
      pagination,
      ideasStore,
      activeTab,
      pendingModerationCount,
      currentUserId,
      showNewIdeaDialog,
      showEditIdeaDialog,
      showDeleteDialog,
      submitting,
      submittingEdit,
      currentPage,
      selectedCategory,
      selectedChannel,
      selectedStatus,
      searchText,
      selectedSort,
      newIdea,
      editIdeaForm,
      expandedComments,
      commentsLoading,
      categoryOptions,
      channelOptions,
      statusOptions,
      sortOptions,
      editorToolbar,
      fileInput,
      editFileInput,
      uploadingImage,
      onChannelSelect,
      onFilterChange,
      onPageChange,
      onFileSelected,
      onEditFileSelected,
      onSubmitIdea,
      resetNewIdea,
      onEditIdea,
      onSubmitEdit,
      onDeleteIdea,
      onConfirmDelete,
      getCommentCount,
      onToggleComments,
      onDeleteComment,
      onVoteIdea,
      onVoteComment,
      onUpdateStatus,
      onShowIdea,
    };
  },
});
</script>

<style lang="scss">
// Shadcn's --input / --border tokens (#e2e8f0, slate-200) are nearly
// invisible against the white card; bump to slate-300 on the Idea Board
// inputs so the field outlines actually read. q-editor doesn't get any
// shadcn treatment at all, so it needs the border drawn here too.
//
// Not scoped because q-dialog teleports its content to <body> — scoped
// rules wouldn't reach the dialog's inputs. Targeting via `.ideas-dialog-card`
// (set on the dialog's q-card) keeps the blast radius to this page.

.ideas-dialog-card {
  .q-input.q-field--outlined .q-field__control,
  .q-select.q-field--outlined .q-field__control {
    border-color: #cbd5e1;

    &:hover { border-color: var(--ring); }
  }

  // Quasar's QEditor in this build does NOT emit a `q-editor--bordered`
  // modifier class (see node_modules/quasar/src/components/editor/QEditor.js
  // lines 503-511 — the classes computed only includes --default/--square/
  // --flat/--dense/--dark). The `bordered` attribute on <q-editor> is a
  // no-op, so the border has to be drawn unconditionally on `.q-editor`.
  .q-editor {
    border: 1px solid #cbd5e1;
    border-radius: 6px;
    overflow: hidden;

    .q-editor__toolbar {
      border-bottom: 1px solid #cbd5e1;
    }

    &:focus-within { border-color: var(--ring); }
  }

  .idea-editor-content {
    ul,
    ol {
      margin: 0 0 4px;
      padding-left: 24px;
    }

    ul { list-style: disc; }
    ol { list-style: decimal; }

    // `anywhere` rather than `break-word`: both wrap a long unbroken string
    // (pasted URL, token, keysmash), but only `anywhere` also shrinks the
    // element's min-content width, so the string can't widen the dialog.
    overflow-wrap: anywhere;

    // The image button inserts `max-width:100%` inline, but drag/paste goes
    // straight through contenteditable and arrives unstyled.
    img {
      max-width: 100%;
      height: auto;
    }
  }
}

// overflow-x must stay `auto`, not `hidden`: `hidden` still lets content
// overflow, it just makes it unreachable — which is exactly what left the
// Category/Channel fields stranded off-screen (DOCB-13610).
body.body--shadcn .q-dialog__inner > .q-card.ideas-dialog-card {
  max-height: 90vh;
  overflow-y: auto;
  overflow-x: auto;
}
</style>

