<template>
  <div class="idea-attachments">
    <!-- Upload area -->
    <div v-if="canUpload" class="q-mb-sm">
      <q-btn
        flat
        dense
        no-caps
        icon="attach_file"
        :label="$t('attach_files')"
        :loading="uploading"
        color="grey-7"
        @click="fileInput?.click()"
      />
      <input
        ref="fileInput"
        type="file"
        accept="image/jpeg,image/png,image/gif,image/webp,application/pdf"
        multiple
        style="display: none"
        @change="onFilesSelected"
      />
      <div v-if="uploadError" class="text-caption text-negative q-mt-xs">
        {{ uploadError }}
      </div>
    </div>

    <!-- Attachment grid -->
    <div v-if="assets.length > 0" class="row q-gutter-sm q-mt-xs">
      <div
        v-for="asset in assets"
        :key="asset.id"
        class="attachment-item"
      >
        <!-- Image thumbnail -->
        <div v-if="isImage(asset.mime_type)" class="attachment-thumb">
          <img
            :src="streamUrl(asset.url)"
            :alt="asset.filename || 'attachment'"
            class="attachment-img"
            @click="$emit('preview', streamUrl(asset.url))"
          />
          <q-btn
            v-if="canDelete(asset)"
            round
            flat
            dense
            size="xs"
            icon="close"
            color="negative"
            class="attachment-delete"
            @click="onDelete(asset.id)"
          />
        </div>
        <!-- PDF icon -->
        <div v-else class="attachment-file">
          <a :href="streamUrl(asset.url)" target="_blank" class="text-decoration-none">
            <q-icon name="picture_as_pdf" size="32px" color="red-7" />
            <div class="text-caption text-grey-7 ellipsis" style="max-width: 80px">
              {{ asset.filename || 'file.pdf' }}
            </div>
          </a>
          <q-btn
            v-if="canDelete(asset)"
            round
            flat
            dense
            size="xs"
            icon="close"
            color="negative"
            class="attachment-delete"
            @click="onDelete(asset.id)"
          />
        </div>
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, ref, type PropType } from 'vue';
import { useIdeasStore } from 'src/store/main';
import { IDEAS_URL } from 'src/pages/APIs';
import type { IdeaAsset } from 'src/types/api/ideas';

const MAX_FILE_SIZE = 5 * 1024 * 1024; // 5MB

export default defineComponent({
  name: 'IdeaAttachments',

  props: {
    ideaId: { type: String, required: true },
    assets: { type: Array as PropType<IdeaAsset[]>, default: () => [] },
    currentUserId: { type: Number, default: 0 },
    canUpload: { type: Boolean, default: false },
  },

  emits: ['uploaded', 'deleted', 'preview'],

  setup(props, { emit }) {
    const ideasStore = useIdeasStore();
    const fileInput = ref<HTMLInputElement | null>(null);
    const uploading = ref(false);
    const uploadError = ref('');

    function isImage(mimeType: string | null): boolean {
      return !!mimeType && mimeType.startsWith('image/');
    }

    function streamUrl(url: string): string {
      if (url.startsWith('/')) return IDEAS_URL + url;
      return url;
    }

    function canDelete(asset: IdeaAsset): boolean {
      return asset.created_by === props.currentUserId;
    }

    async function onFilesSelected(event: Event) {
      const target = event.target as HTMLInputElement;
      const files = target.files;
      if (!files || files.length === 0) return;

      uploadError.value = '';
      uploading.value = true;

      try {
        for (const file of Array.from(files)) {
          if (file.size > MAX_FILE_SIZE) {
            uploadError.value = `${file.name} exceeds 5MB limit`;
            continue;
          }
          await ideasStore.uploadAsset(props.ideaId, file);
        }
        emit('uploaded');
      } catch {
        uploadError.value = 'Upload failed';
      } finally {
        uploading.value = false;
        if (fileInput.value) fileInput.value.value = '';
      }
    }

    async function onDelete(assetId: string) {
      try {
        await ideasStore.removeAsset(props.ideaId, assetId);
        emit('deleted');
      } catch {
        // handled in store
      }
    }

    return {
      fileInput,
      uploading,
      uploadError,
      isImage,
      streamUrl,
      canDelete,
      onFilesSelected,
      onDelete,
    };
  },
});
</script>

