export type IdeaCategory = 'feature' | 'improvement' | 'bug' | 'integration' | 'other';
export type IdeaStatus = 'new' | 'under_review' | 'planned' | 'in_progress' | 'done' | 'declined';
export type IdeaChannel = 'general' | 'docnet' | 'workflow' | 'dashboard' | 'import_export' | 'document_processing';
export type VoteDirection = 'up' | 'down';

export interface Idea {
  id: string;
  title: string;
  description: string | null;
  category: IdeaCategory;
  channel: IdeaChannel;
  status: IdeaStatus;
  vote_count: number;
  upvote_count: number;
  downvote_count: number;
  moderation_status: ModerationStatus;
  moderated_by?: number | null;
  moderated_at?: string | null;
  user_vote?: 1 | -1 | 0;
  comment_count?: number;
  creator_name: string | null;
  creator_org_name: string | null;
  creator_org_id: string;
  created_on: string | null;
  created_by: number | null;
}

export interface PaginationInfo {
  current_page: number;
  page_size: number;
  total_entries: number;
  total_pages: number;
  has_next_page: boolean;
}

export interface IdeasListResponse {
  success: boolean;
  ideas: Idea[];
  pagination: PaginationInfo;
}

export interface IdeaSingleResponse {
  success: boolean;
  idea: Idea;
}

export interface CreateIdeaPayload {
  title: string;
  description?: string;
  category: IdeaCategory;
  channel?: IdeaChannel;
  creator_name?: string;
}

export interface VoteResponse {
  success: boolean;
  voted: boolean;
  vote_count: number;
  upvote_count: number;
  downvote_count: number;
  direction?: VoteDirection;
}

export interface MyVotesResponse {
  success: boolean;
  idea_votes: Record<string, 1 | -1>;
  comment_votes: Record<string, 1 | -1>;
}

export interface VotePayload {
  direction: VoteDirection;
}

export interface CommentVoteResponse {
  success: boolean;
  voted: boolean;
  vote_count: number;
  direction?: VoteDirection;
}

export interface UpdateIdeaPayload {
  title?: string;
  description?: string;
  category?: IdeaCategory;
  channel?: IdeaChannel;
}

export interface IdeaAsset {
  id: string;
  filename: string | null;
  mime_type: string | null;
  url: string;
  created_by: number | null;
  created_on: string | null;
}

export interface AssetsListResponse {
  success: boolean;
  assets: IdeaAsset[];
}

export type ModerationStatus = 'approved' | 'pending' | 'rejected' | 'hidden';

export interface IdeaComment {
  id: string;
  idea_id: string;
  user_id: number;
  content: string;
  creator_name: string | null;
  creator_org_name: string | null;
  moderation_status?: ModerationStatus;
  vote_count: number;
  user_vote?: 1 | -1 | 0;
  created_on: string | null;
  created_by: number | null;
}

export interface PendingComment {
  id: string;
  idea_id: string;
  user_id: number;
  content: string;
  creator_name: string | null;
  creator_org_name: string | null;
  moderation_status: ModerationStatus;
  created_on: string | null;
  idea_title: string;
}

export interface PendingCommentsResponse {
  success: boolean;
  comments: PendingComment[];
  count: number;
}

export interface PendingIdea {
  id: string;
  title: string;
  description: string | null;
  category: IdeaCategory;
  channel: IdeaChannel;
  moderation_status: ModerationStatus;
  created_on: string | null;
  creator_name: string | null;
  creator_org_name: string | null;
  creator_org_id: string;
  created_by: number | null;
}

export interface PendingIdeasResponse {
  success: boolean;
  ideas: PendingIdea[];
  count: number;
}

export interface TrustedOrg {
  id: string;
  org_id: string;
  org_name: string;
  created_by: string;
  created_on: string;
}

export interface TrustedOrgsResponse {
  success: boolean;
  trusted_orgs: TrustedOrg[];
}

export interface CreateCommentPayload {
  content: string;
  creator_name?: string;
}

export interface CommentsListResponse {
  success: boolean;
  comments: IdeaComment[];
}

