<template>
  <div class="inline-flex items-center gap-2">
    <button
      class="inline-flex items-center rounded-full bg-muted transition-colors hover:bg-accent disabled:opacity-40 disabled:cursor-not-allowed"
      :class="[
        userVote === 1 ? 'text-primary font-semibold' : 'text-muted-foreground',
        size === 'small' ? 'gap-1 px-2 py-0.5' : 'gap-1.5 px-3 py-1',
      ]"
      :aria-label="$t('vote_up')"
      :aria-pressed="userVote === 1"
      :disabled="disabled"
      @click.stop="$emit('vote', 'up')"
    >
      <Icon
        :icon="userVote === 1 ? 'mdi:thumb-up' : 'mdi:thumb-up-outline'"
        :class="size === 'small' ? 'size-4' : 'size-5'"
      />
      <span
        class="tabular-nums select-none"
        :class="size === 'small' ? 'text-xs' : 'text-sm'"
      >
        {{ upCount }}
      </span>
    </button>
    <button
      class="inline-flex items-center rounded-full bg-muted transition-colors hover:bg-accent disabled:opacity-40 disabled:cursor-not-allowed"
      :class="[
        userVote === -1 ? 'text-destructive font-semibold' : 'text-muted-foreground',
        size === 'small' ? 'gap-1 px-2 py-0.5' : 'gap-1.5 px-3 py-1',
      ]"
      :aria-label="$t('vote_down')"
      :aria-pressed="userVote === -1"
      :disabled="disabled"
      @click.stop="$emit('vote', 'down')"
    >
      <Icon
        :icon="userVote === -1 ? 'mdi:thumb-down' : 'mdi:thumb-down-outline'"
        :class="size === 'small' ? 'size-4' : 'size-5'"
      />
      <span
        class="tabular-nums select-none"
        :class="size === 'small' ? 'text-xs' : 'text-sm'"
      >
        {{ downCount }}
      </span>
    </button>
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { Icon } from '@iconify/vue';
import type { VoteDirection } from 'src/types/api/ideas';

export default defineComponent({
  name: 'IdeaThumbVote',
  components: { Icon },

  props: {
    upCount: { type: Number, required: true },
    downCount: { type: Number, required: true },
    userVote: { type: Number as () => 1 | -1 | 0, default: 0 },
    size: { type: String as () => 'default' | 'small', default: 'default' },
    disabled: { type: Boolean, default: false },
  },

  emits: {
    vote: (direction: VoteDirection) => direction === 'up' || direction === 'down',
  },
});
</script>
