<template>
  <q-dialog
    :model-value="!!src"
    maximized
    @update:model-value="(open) => { if (!open) $emit('close'); }"
  >
    <div class="idea-image-viewer" @click="$emit('close')">
      <q-btn
        round
        flat
        icon="close"
        class="idea-image-viewer__close"
        :aria-label="$t('close')"
        @click.stop="$emit('close')"
      />
      <img
        v-if="src"
        :src="src"
        alt=""
        class="idea-image-viewer__img"
        @click.stop
      />
    </div>
  </q-dialog>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';

export default defineComponent({
  name: 'IdeaImageViewer',

  props: {
    src: { type: String as PropType<string | null>, default: null },
  },

  emits: {
    close: () => true,
  },
});
</script>

<style scoped>
.idea-image-viewer {
  position: relative;
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
