<template>
  <div class="mt-5 -mx-4 -mb-4 border-t border-border bg-muted/50 px-4 py-4 rounded-b-xl">
    <div class="flex items-center gap-2 mb-3">
      <span class="text-xs font-semibold text-foreground">{{ $t('idea_comments') }}</span>
    </div>

    <!-- Loading -->
    <div v-if="loading" class="flex justify-center py-4">
      <q-spinner size="24px" color="primary" />
    </div>

    <template v-else>
      <!-- Comment list -->
      <div class="flex flex-col gap-2 mb-3">
        <IdeaCommentItem
          v-for="comment in comments"
          :key="comment.id"
          :comment="comment"
          :current-user-id="currentUserId"
          :user-vote="getCommentVote(comment.id)"
          :is-moderator="isModerator"
          :action-loading="!!hiding[comment.id]"
          @vote="onCommentVote"
          @delete="onDeleteComment"
          @hide="onHideComment"
        />
        <div v-if="comments.length === 0" class="text-sm text-muted-foreground text-center py-3">
          {{ $t('no_comments_yet') }}
        </div>
      </div>

      <!-- Comment input -->
      <div class="flex gap-2">
        <q-input
          v-model="commentText"
          dense
          outlined
          :placeholder="$t('add_comment') + '...'"
          class="flex-1"
          @keyup.enter="onSubmit"
        />
        <q-btn
          color="primary"
          dense
          round
          :disable="!commentText.trim()"
          :loading="submitting"
          @click="onSubmit"
        >
          <Icon icon="mdi:send" class="size-4" />
        </q-btn>
      </div>
    </template>
  </div>
</template>

<script lang="ts">
import { defineComponent, ref, reactive, type PropType } from 'vue';
import { Icon } from '@iconify/vue';
import type { IdeaComment, VoteDirection } from 'src/types/api/ideas';
import IdeaCommentItem from './IdeaCommentItem.vue';
import { useIdeasStore } from 'src/store/main';
import { DocBitsNotification } from 'src/components/DocBitsNotification';

export default defineComponent({
  name: 'IdeaCommentSection',
  components: { Icon, IdeaCommentItem },

  props: {
    ideaId: { type: String, required: true },
    comments: { type: Array as PropType<IdeaComment[]>, default: () => [] },
    currentUserId: { type: Number, required: true },
    isModerator: { type: Boolean, default: false },
    loading: { type: Boolean, default: false },
    getCommentVote: { type: Function as PropType<(commentId: string) => 1 | -1 | 0>, required: true },
  },

  emits: {
    'delete-comment': (ideaId: string, commentId: string) => !!ideaId && !!commentId,
    'vote-comment': (ideaId: string, commentId: string, direction: VoteDirection) => !!ideaId && !!commentId && !!direction,
  },

  setup(props, { emit }) {
    const ideasStore = useIdeasStore();
    const commentText = ref('');
    const submitting = ref(false);
    const hiding = reactive<Record<string, boolean>>({});

    async function onSubmit() {
      const text = commentText.value.trim();
      if (!text) return;
      commentText.value = '';
      submitting.value = true;
      try {
        await ideasStore.addComment(props.ideaId, text);
      } finally {
        submitting.value = false;
      }
    }

    function onCommentVote(commentId: string, direction: VoteDirection) {
      emit('vote-comment', props.ideaId, commentId, direction);
    }

    function onDeleteComment(commentId: string) {
      emit('delete-comment', props.ideaId, commentId);
    }

    async function onHideComment(commentId: string) {
      hiding[commentId] = true;
      try {
        await ideasStore.hideComment(commentId, props.ideaId);
      } catch {
        // Error notification already shown by store
      } finally {
        hiding[commentId] = false;
      }
    }

    return {
      commentText,
      submitting,
      hiding,
      onSubmit,
      onCommentVote,
      onDeleteComment,
      onHideComment,
    };
  },
});
</script>
