<template>
  <div
    class="rounded-lg border bg-card p-3"
    :class="[
      // Moderation tinting is for moderators only — authors don't know the
      // approval flow exists, so a pending/rejected comment must look like
      // a normal posted comment to them.
      isModerator && comment.moderation_status === 'rejected' ? 'border-destructive/40 bg-destructive/5' :
      isModerator && comment.moderation_status === 'pending' ? 'border-warning/40 bg-warning/5' :
      isModerator && comment.moderation_status === 'hidden' ? 'border-border bg-muted/30 opacity-70' :
      'border-border'
    ]"
  >
    <!-- Header: avatar + name + timestamp + moderation badge -->
    <div class="flex items-center gap-2 mb-1.5">
      <div
        class="size-7 rounded-full flex items-center justify-center text-xs font-semibold text-primary-foreground shrink-0"
        :style="{ backgroundColor: avatarColor }"
      >
        {{ initials }}
      </div>
      <span class="text-sm font-medium text-foreground">{{ comment.creator_name || comment.creator_org_name || $t('unknown_user') }}</span>
      <span v-if="comment.created_on" class="text-xs text-muted-foreground">
        &middot; {{ timeAgo(comment.created_on) }}
      </span>
      <span
        v-if="isModerator && comment.moderation_status === 'pending'"
        class="text-[10px] font-medium uppercase tracking-wide px-1.5 py-0.5 rounded bg-warning/15 text-warning border border-warning/30"
      >
        {{ $t('pending') }}
      </span>
      <span
        v-if="isModerator && comment.moderation_status === 'rejected'"
        class="text-[10px] font-medium uppercase tracking-wide px-1.5 py-0.5 rounded bg-destructive/10 text-destructive border border-destructive/30"
      >
        {{ $t('rejected') }}
      </span>
      <span
        v-if="isModerator && comment.moderation_status === 'hidden'"
        class="text-[10px] font-medium uppercase tracking-wide px-1.5 py-0.5 rounded bg-muted text-muted-foreground border border-border"
      >
        {{ $t('hidden') || 'Hidden' }}
      </span>
    </div>

    <!-- Content -->
    <div class="text-sm text-foreground mb-2 ml-9">{{ comment.content }}</div>

    <!-- Bottom action bar -->
    <div class="flex items-center gap-3 ml-9">
      <IdeaVoteButton
        :score="comment.vote_count ?? 0"
        :user-vote="userVote"
        :disabled="isOwnComment"
        size="small"
        @vote="onVote"
      />
      <q-spinner v-if="actionLoading" size="16px" color="primary" />
      <IdeaActionMenu
        v-else-if="menuItems.length > 0"
        :items="menuItems"
        size="sm"
        @action="onAction"
      />
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, computed, type PropType } from 'vue';
import { useI18n } from 'vue-i18n';
import type { IdeaComment, VoteDirection } from 'src/types/api/ideas';
import IdeaVoteButton from './IdeaVoteButton.vue';
import IdeaActionMenu, { type ActionMenuItem } from './IdeaActionMenu.vue';

const AVATAR_COLORS = [
  '#2388AE', '#10B981', '#F59E0B', '#EF4444', '#8B5CF6',
  '#EC4899', '#06B6D4', '#84CC16', '#F97316', '#6366F1',
];

function hashCode(str: string): number {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    hash = str.charCodeAt(i) + ((hash << 5) - hash);
  }
  return Math.abs(hash);
}

export default defineComponent({
  name: 'IdeaCommentItem',
  components: { IdeaVoteButton, IdeaActionMenu },

  props: {
    comment: { type: Object as PropType<IdeaComment>, required: true },
    currentUserId: { type: Number, required: true },
    userVote: { type: Number as () => 1 | -1 | 0, default: 0 },
    isModerator: { type: Boolean, default: false },
    actionLoading: { type: Boolean, default: false },
  },

  emits: {
    vote: (commentId: string, direction: VoteDirection) => !!commentId && !!direction,
    delete: (commentId: string) => !!commentId,
    hide: (commentId: string) => !!commentId,
  },

  setup(props, { emit }) {
    const { t } = useI18n();
    const isOwnComment = computed(() => props.comment.user_id === props.currentUserId);

    const commentDisplayName = computed(() =>
      props.comment.creator_name || props.comment.creator_org_name || 'Unknown',
    );

    const initials = computed(() => {
      const name = commentDisplayName.value;
      const parts = name.split(' ').filter(Boolean);
      if (parts.length >= 2) return (parts[0][0] + parts[1][0]).toUpperCase();
      return name.substring(0, 2).toUpperCase();
    });

    const avatarColor = computed(() => {
      return AVATAR_COLORS[hashCode(commentDisplayName.value) % AVATAR_COLORS.length];
    });

    const menuItems = computed<ActionMenuItem[]>(() => {
      const items: ActionMenuItem[] = [];
      if (props.isModerator && props.comment.moderation_status === 'approved') {
        items.push({
          action: 'hide',
          label: 'hide_for_others',
          icon: 'mdi:eye-off-outline',
        });
      }
      if (isOwnComment.value || props.isModerator) {
        items.push({
          action: 'delete',
          label: 'delete',
          icon: 'mdi:delete-outline',
          destructive: true,
        });
      }
      return items;
    });

    function timeAgo(dateStr: string): string {
      const date = new Date(dateStr);
      const now = new Date();
      const seconds = Math.floor((now.getTime() - date.getTime()) / 1000);
      if (seconds < 60) return t('just_now');
      const minutes = Math.floor(seconds / 60);
      if (minutes < 60) return t('minutes_ago', { n: minutes });
      const hours = Math.floor(minutes / 60);
      if (hours < 24) return t('hours_ago', { n: hours });
      const days = Math.floor(hours / 24);
      if (days < 30) return t('days_ago', { n: days });
      const months = Math.floor(days / 30);
      return t('months_ago', { n: months });
    }

    function onVote(direction: VoteDirection) {
      emit('vote', props.comment.id, direction);
    }

    function onAction(action: string) {
      if (action === 'delete') emit('delete', props.comment.id);
      if (action === 'hide') emit('hide', props.comment.id);
    }

    return {
      isOwnComment,
      initials,
      avatarColor,
      menuItems,
      timeAgo,
      onVote,
      onAction,
    };
  },
});
</script>
