<template>
  <q-card flat class="rounded-xl border border-border shadow-[0_1px_3px_rgba(0,0,0,0.04)]">
    <q-card-section class="p-5">
      <!-- Badges row -->
      <div class="flex items-center gap-2 mb-2 flex-wrap">
        <span class="idea-badge" :class="categoryBadgeClass">
          {{ $t('idea_category_' + idea.category) }}
        </span>
        <span class="idea-badge idea-badge-neutral">
          {{ $t('idea_channel_' + idea.channel) }}
        </span>
        <span
          v-if="isModerator"
          class="idea-badge idea-badge-clickable"
          :class="statusBadgeClass"
          :aria-label="$t('idea_change_status')"
        >
          {{ $t('idea_status_' + idea.status) }}
          <Icon icon="mdi:chevron-down" class="size-3.5 -mr-0.5" />
          <q-menu anchor="bottom left" self="top left">
            <q-list dense style="min-width: 160px">
              <q-item
                v-for="opt in statusOptions"
                :key="opt.value"
                v-close-popup
                clickable
                :active="opt.value === idea.status"
                :data-status="opt.value"
                @click="onStatusPick(opt.value)"
              >
                <q-item-section avatar>
                  <Icon
                    :icon="opt.value === idea.status ? 'mdi:radiobox-marked' : 'mdi:radiobox-blank'"
                    class="size-4"
                  />
                </q-item-section>
                <q-item-section>{{ $t(opt.label) }}</q-item-section>
              </q-item>
            </q-list>
          </q-menu>
        </span>
        <span v-else class="idea-badge" :class="statusBadgeClass">
          {{ $t('idea_status_' + idea.status) }}
        </span>
        <span
          v-if="isModerator && idea.moderation_status === 'pending'"
          class="idea-badge idea-badge-warning"
        >
          {{ $t('pending') }}
        </span>
        <span
          v-if="isModerator && idea.moderation_status === 'rejected'"
          class="idea-badge idea-badge-destructive"
        >
          {{ $t('rejected') }}
        </span>
      </div>

      <!-- Title -->
      <h3 class="text-lg font-semibold text-foreground mb-1">{{ idea.title }}</h3>

      <!-- Description -->
      <div
        v-if="sanitizedDescription"
        class="idea-description text-sm text-foreground mb-2"
        v-html="sanitizedDescription"
        @click="onDescriptionClick"
      />

      <!-- Author + timestamp -->
      <div class="text-xs text-muted-foreground mb-3">
        {{ idea.creator_name || idea.creator_org_name || $t('unknown_user') }}
        <span v-if="idea.creator_org_name"> · {{ idea.creator_org_name }}</span>
        <span v-if="idea.created_on"> · {{ formatDate(idea.created_on) }}</span>
      </div>

      <!-- Bottom action bar -->
      <div
        class="flex items-center gap-3 pt-3 border-t border-border"
        :class="showComments ? 'pb-3' : ''"
      >
        <IdeaThumbVote
          :up-count="idea.upvote_count"
          :down-count="idea.downvote_count"
          :user-vote="userVote"
          @vote="$emit('vote-idea', idea.id, $event)"
        />

        <div class="w-px h-5 bg-border" />

        <!-- Comments toggle -->
        <button
          class="inline-flex items-center gap-1 text-sm text-primary hover:opacity-80 transition-opacity"
          @click="$emit('toggle-comments', idea.id)"
        >
          <Icon icon="mdi:comment-outline" class="size-4" />
          <span>{{ effectiveCommentCount }}</span>
        </button>

        <!-- Action menu (creator only) -->
        <IdeaActionMenu
          v-if="cardMenuItems.length > 0"
          :items="cardMenuItems"
          class="ml-auto"
          @action="onMenuAction"
        />
      </div>

      <!-- Attachments -->
      <IdeaAttachments
        v-if="showComments && assets.length > 0"
        :idea-id="idea.id"
        :assets="assets"
        :current-user-id="currentUserId"
        :can-upload="isCreator"
        class="mt-3"
        @preview="openImagePreview"
      />

      <!-- Comment section -->
      <IdeaCommentSection
        v-if="showComments"
        :idea-id="idea.id"
        :comments="comments"
        :current-user-id="currentUserId"
        :is-moderator="isModerator"
        :loading="commentsLoading"
        :get-comment-vote="getCommentVote"
        @delete-comment="onDeleteComment"
        @vote-comment="onVoteComment"
      />
    </q-card-section>

    <IdeaImageViewer :src="previewImageSrc" @close="closeImagePreview" />
  </q-card>
</template>

<script lang="ts">
import { defineComponent, computed, ref, type PropType } from 'vue';
import DOMPurify from 'dompurify';
import { Icon } from '@iconify/vue';
import type { Idea, IdeaComment, IdeaAsset, IdeaStatus, VoteDirection } from 'src/types/api/ideas';
import { IDEA_STATUSES } from 'src/types/api/ideas';
import IdeaThumbVote from './IdeaThumbVote.vue';
import IdeaActionMenu from './IdeaActionMenu.vue';
import type { ActionMenuItem } from './IdeaActionMenu.vue';
import IdeaCommentSection from './IdeaCommentSection.vue';
import IdeaAttachments from './IdeaAttachments.vue';
import IdeaImageViewer from './IdeaImageViewer.vue';

export default defineComponent({
  name: 'IdeaCard',
  components: { Icon, IdeaThumbVote, IdeaActionMenu, IdeaCommentSection, IdeaAttachments, IdeaImageViewer },

  props: {
    idea: { type: Object as PropType<Idea>, required: true },
    currentUserId: { type: Number, required: true },
    userVote: { type: Number as () => 1 | -1 | 0, default: 0 },
    isModerator: { type: Boolean, default: false },
    showComments: { type: Boolean, default: false },
    commentsLoading: { type: Boolean, default: false },
    comments: { type: Array as PropType<IdeaComment[]>, default: () => [] },
    assets: { type: Array as PropType<IdeaAsset[]>, default: () => [] },
    commentCount: { type: Number, default: 0 },
    getCommentVote: {
      type: Function as PropType<(commentId: string) => 1 | -1 | 0>,
      required: true,
    },
  },

  emits: {
    'vote-idea': (ideaId: string, direction: VoteDirection) => !!ideaId && !!direction,
    'toggle-comments': (ideaId: string) => !!ideaId,
    'delete-comment': (ideaId: string, commentId: string) => !!ideaId && !!commentId,
    'vote-comment': (ideaId: string, commentId: string, direction: VoteDirection) =>
      !!ideaId && !!commentId && !!direction,
    'edit-idea': (ideaId: string) => !!ideaId,
    'delete-idea': (ideaId: string) => !!ideaId,
    'update-status': (ideaId: string, status: IdeaStatus) => !!ideaId && !!status,
  },

  setup(props, { emit }) {
    const isCreator = computed(() => props.idea.created_by === props.currentUserId);

    const categoryBadgeClass = computed(() => {
      const map: Record<string, string> = {
        feature: 'idea-cat-feature',
        improvement: 'idea-cat-improvement',
        integration: 'idea-cat-integration',
        other: 'idea-cat-other',
      };
      return map[props.idea.category] ?? 'idea-cat-other';
    });

    const statusBadgeClass = computed(() => {
      const map: Record<string, string> = {
        new: 'idea-status-new',
        under_review: 'idea-status-under_review',
        planned: 'idea-status-planned',
        in_progress: 'idea-status-in_progress',
        done: 'idea-status-done',
        declined: 'idea-status-declined',
      };
      return map[props.idea.status] ?? 'idea-status-new';
    });

    const cardMenuItems = computed<ActionMenuItem[]>(() => {
      if (!isCreator.value && !props.isModerator) return [];
      return [
        { action: 'edit', label: 'edit', icon: 'mdi:pencil' },
        { action: 'delete', label: 'delete', icon: 'mdi:delete', destructive: true },
      ];
    });

    const sanitizedDescription = computed(() => {
      if (!props.idea.description) return '';
      return DOMPurify.sanitize(props.idea.description, {
        ALLOWED_TAGS: [
          'p', 'br', 'strong', 'em', 'b', 'i', 'u', 'ul', 'ol', 'li',
          'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'blockquote', 'img',
          'a', 'pre', 'code', 'span', 'div', 'hr', 'del',
        ],
        ALLOWED_ATTR: ['href', 'target', 'rel', 'class', 'src', 'alt', 'title', 'width', 'height', 'style'],
      });
    });

    const effectiveCommentCount = computed(
      () => props.commentCount || props.idea.comment_count || 0,
    );

    function formatDate(dateStr: string): string {
      try {
        return new Date(dateStr).toLocaleDateString(undefined, {
          year: 'numeric',
          month: 'short',
          day: 'numeric',
        });
      } catch {
        return dateStr;
      }
    }

    function onMenuAction(action: string) {
      if (action === 'edit') emit('edit-idea', props.idea.id);
      else if (action === 'delete') emit('delete-idea', props.idea.id);
    }

    function onDeleteComment(ideaId: string, commentId: string) {
      emit('delete-comment', ideaId, commentId);
    }

    function onVoteComment(ideaId: string, commentId: string, direction: VoteDirection) {
      emit('vote-comment', ideaId, commentId, direction);
    }

    function onStatusPick(next: IdeaStatus) {
      if (next === props.idea.status) return;
      emit('update-status', props.idea.id, next);
    }

    const previewImageSrc = ref<string | null>(null);

    function openImagePreview(src: string) {
      previewImageSrc.value = src;
    }

    function closeImagePreview() {
      previewImageSrc.value = null;
    }

    function onDescriptionClick(event: MouseEvent) {
      const target = event.target as HTMLElement | null;
      if (target?.tagName !== 'IMG') return;
      const src = (target as HTMLImageElement).currentSrc || (target as HTMLImageElement).src;
      if (src) openImagePreview(src);
    }

    return {
      isCreator,
      categoryBadgeClass,
      statusBadgeClass,
      statusOptions: IDEA_STATUSES,
      cardMenuItems,
      sanitizedDescription,
      effectiveCommentCount,
      formatDate,
      onMenuAction,
      onDeleteComment,
      onVoteComment,
      onStatusPick,
      previewImageSrc,
      openImagePreview,
      closeImagePreview,
      onDescriptionClick,
    };
  },
});
</script>

