<template>
  <q-btn flat round dense :size="size" @click.stop>
    <Icon icon="mdi:dots-vertical" :class="size === 'sm' ? 'size-4' : 'size-5'" class="text-muted-foreground" />
    <q-menu auto-close>
      <q-list dense>
        <template v-for="(item, idx) in items" :key="item.action">
          <q-separator v-if="item.destructive && idx > 0" />
          <q-item
            clickable
            :class="item.destructive ? 'text-negative' : ''"
            class="min-h-0 px-3 py-1.5"
            @click="$emit('action', item.action)"
          >
            <div class="flex items-center gap-2">
              <q-icon :name="item.destructive ? 'delete' : undefined" size="xs" v-if="item.destructive" />
              <Icon v-else :icon="item.icon" class="size-4 text-muted-foreground" />
              <span class="text-sm">{{ $t(item.label) }}</span>
            </div>
          </q-item>
        </template>
      </q-list>
    </q-menu>
  </q-btn>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import { Icon } from '@iconify/vue';

export interface ActionMenuItem {
  action: string;
  label: string;
  icon: string;
  destructive?: boolean;
}

export default defineComponent({
  name: 'IdeaActionMenu',
  components: { Icon },

  props: {
    items: { type: Array as PropType<ActionMenuItem[]>, required: true },
    size: { type: String as () => 'sm' | 'md', default: 'sm' },
  },

  emits: {
    action: (action: string) => typeof action === 'string',
  },
});
</script>
