<template>
  <div class="p-4 flex flex-col gap-6">
    <!-- Pending Ideas section -->
    <section>
      <div class="text-sm font-semibold text-foreground mb-4 flex items-center gap-2">
        {{ $t('pending_ideas') || 'Pending Ideas' }}
        <span
          v-if="pendingIdeas.length > 0"
          class="text-xs font-medium text-warning bg-warning/10 border border-warning/30 rounded-full px-2 py-0.5"
        >
          {{ pendingIdeas.length }} {{ $t('pending') }}
        </span>
      </div>

      <div v-if="loadingPending" class="flex justify-center py-8">
        <q-spinner size="36px" color="primary" />
      </div>

      <div v-else-if="pendingIdeas.length === 0" class="flex flex-col items-center py-8 text-muted-foreground">
        <Icon icon="mdi:check-circle-outline" class="size-12 mb-2" />
        <div class="text-sm">{{ $t('no_pending_ideas') || 'No ideas awaiting review.' }}</div>
      </div>

      <div v-else class="flex flex-col gap-3">
        <q-card
          v-for="idea in pendingIdeas"
          :key="idea.id"
          flat
          class="rounded-lg border-l-4 border-warning bg-card border border-border"
        >
          <q-card-section class="p-5">
            <div class="flex items-center gap-2 mb-2">
              <Icon icon="mdi:lightbulb-outline" class="size-4 text-warning shrink-0" />
              <span class="text-sm font-medium text-foreground">
                {{ idea.creator_name || idea.creator_org_name || $t('unknown_user') || 'Unknown' }}
              </span>
              <span v-if="idea.creator_org_name" class="text-xs font-medium text-muted-foreground bg-muted px-2 py-0.5 rounded-md">
                {{ idea.creator_org_name }}
              </span>
            </div>
            <div class="text-base font-semibold text-foreground mb-1">{{ idea.title }}</div>
            <div
              v-if="ideaDescriptionsHtml[idea.id]"
              class="moderation-idea-description text-sm text-muted-foreground mb-3"
              v-html="ideaDescriptionsHtml[idea.id]"
            />
            <div class="flex items-center gap-2 mb-4 text-xs text-muted-foreground">
              <span class="bg-muted px-2 py-0.5 rounded-md">{{ idea.category }}</span>
              <span class="bg-muted px-2 py-0.5 rounded-md">{{ idea.channel }}</span>
            </div>
            <div class="flex gap-2">
              <button
                class="inline-flex items-center gap-1.5 text-xs font-medium px-3 py-1.5 rounded-md text-positive bg-positive/10 border border-positive/30 hover:bg-positive/20 transition-colors disabled:opacity-50"
                :disabled="moderatingIdeas[idea.id]"
                @click="onModerateIdea(idea.id, 'approve')"
              >
                <Icon icon="mdi:check" class="size-4" />
                {{ $t('approve') }}
              </button>
              <button
                class="inline-flex items-center gap-1.5 text-xs font-medium px-3 py-1.5 rounded-md text-destructive bg-destructive/10 border border-destructive/20 hover:bg-destructive/20 transition-colors disabled:opacity-50"
                :disabled="moderatingIdeas[idea.id]"
                @click="onModerateIdea(idea.id, 'reject')"
              >
                <Icon icon="mdi:close" class="size-4" />
                {{ $t('reject') }}
              </button>
            </div>
          </q-card-section>
        </q-card>
      </div>
    </section>

    <!-- Pending Comments section -->
    <section>
      <div class="text-sm font-semibold text-foreground mb-4 flex items-center gap-2">
        {{ $t('pending_comments') }}
        <span
          v-if="pendingComments.length > 0"
          class="text-xs font-medium text-warning bg-warning/10 border border-warning/30 rounded-full px-2 py-0.5"
        >
          {{ pendingComments.length }} {{ $t('pending') }}
        </span>
      </div>

      <div v-if="loadingPending" class="flex justify-center py-8">
        <q-spinner size="36px" color="primary" />
      </div>

      <div v-else-if="pendingComments.length === 0" class="flex flex-col items-center py-8 text-muted-foreground">
        <Icon icon="mdi:check-circle-outline" class="size-12 mb-2" />
        <div class="text-sm">{{ $t('no_pending_comments') }}</div>
      </div>

      <div v-else class="flex flex-col gap-3">
        <q-card
          v-for="comment in pendingComments"
          :key="comment.id"
          flat
          class="rounded-lg border-l-4 border-warning bg-card border border-border"
        >
          <q-card-section class="p-5">
            <div class="flex items-center gap-2 mb-2">
              <Icon icon="mdi:alert-outline" class="size-4 text-warning shrink-0" />
              <span class="text-sm font-medium text-foreground">{{ comment.creator_name || comment.creator_org_name || $t('unknown_user') || 'Unknown' }}</span>
              <span v-if="comment.creator_org_name" class="text-xs font-medium text-muted-foreground bg-muted px-2 py-0.5 rounded-md">
                {{ comment.creator_org_name }}
              </span>
            </div>
            <div class="text-xs text-muted-foreground mb-2 flex items-center gap-1">
              <span>on:</span>
              <button class="text-primary hover:underline font-medium inline-flex items-center gap-1" @click="$emit('show-idea', comment.idea_id)">
                <Icon icon="mdi:link-variant" class="size-3.5" />
                {{ comment.idea_title }}
              </button>
            </div>
            <div class="text-sm text-foreground mb-4">{{ comment.content }}</div>
            <div class="flex gap-2">
              <button
                class="inline-flex items-center gap-1.5 text-xs font-medium px-3 py-1.5 rounded-md text-positive bg-positive/10 border border-positive/30 hover:bg-positive/20 transition-colors disabled:opacity-50"
                :disabled="moderating[comment.id]"
                @click="onModerate(comment.id, 'approve')"
              >
                <Icon icon="mdi:check" class="size-4" />
                {{ $t('approve') }}
              </button>
              <button
                class="inline-flex items-center gap-1.5 text-xs font-medium px-3 py-1.5 rounded-md text-destructive bg-destructive/10 border border-destructive/20 hover:bg-destructive/20 transition-colors disabled:opacity-50"
                :disabled="moderating[comment.id]"
                @click="onModerate(comment.id, 'reject')"
              >
                <Icon icon="mdi:close" class="size-4" />
                {{ $t('reject') }}
              </button>
            </div>
          </q-card-section>
        </q-card>
      </div>
    </section>
  </div>
</template>

<script lang="ts">
import { defineComponent, ref, reactive, onMounted, computed } from 'vue';
import { storeToRefs } from 'pinia';
import { Icon } from '@iconify/vue';
import DOMPurify from 'dompurify';
import { useIdeasStore } from 'src/store/main';

export default defineComponent({
  name: 'IdeaModerationTab',
  components: { Icon },

  emits: {
    'show-idea': (ideaId: string) => !!ideaId,
  },

  setup() {
    const ideasStore = useIdeasStore();
    const { pendingComments, pendingIdeas } = storeToRefs(ideasStore);
    const loadingPending = ref(true);
    const moderating = reactive<Record<string, boolean>>({});
    const moderatingIdeas = reactive<Record<string, boolean>>({});

    // Idea descriptions are rich HTML (q-editor output, may include inline
    // base64 images). Sanitize each one through DOMPurify so v-html is safe;
    // the matching .moderation-idea-description CSS caps height to keep the
    // queue compact.
    const ideaDescriptionsHtml = computed<Record<string, string>>(() => {
      const out: Record<string, string> = {};
      for (const idea of pendingIdeas.value) {
        if (idea.description) {
          out[idea.id] = DOMPurify.sanitize(idea.description, {
            ALLOWED_TAGS: ['p', 'br', 'b', 'i', 'u', 'strong', 'em', 'a', 'ul', 'ol', 'li', 'img', 'span', 'div'],
            ALLOWED_ATTR: ['href', 'target', 'rel', 'src', 'alt', 'title'],
            ALLOWED_URI_REGEXP: /^(?:https?|data):/i,
          });
        }
      }
      return out;
    });

    async function loadData() {
      loadingPending.value = true;
      try {
        await Promise.all([
          ideasStore.loadPendingComments(),
          ideasStore.loadPendingIdeas(),
        ]);
      } finally { loadingPending.value = false; }
    }

    async function onModerate(commentId: string, action: 'approve' | 'reject') {
      moderating[commentId] = true;
      try {
        await ideasStore.moderateComment(commentId, action);
      } catch {
        // Error notification already shown by store
      } finally {
        moderating[commentId] = false;
      }
    }

    async function onModerateIdea(ideaId: string, action: 'approve' | 'reject') {
      moderatingIdeas[ideaId] = true;
      try {
        await ideasStore.moderateIdea(ideaId, action);
      } catch {
        // Error notification already shown by store
      } finally {
        moderatingIdeas[ideaId] = false;
      }
    }

    onMounted(loadData);

    return {
      pendingComments,
      pendingIdeas,
      loadingPending,
      moderating,
      moderatingIdeas,
      ideaDescriptionsHtml,
      onModerate,
      onModerateIdea,
    };
  },
});
</script>

<style lang="scss" scoped>
// Pending-idea descriptions can contain large inline base64 images.
// Cap the rendered region so a single tall image doesn't push the moderation
// actions off-screen, and scroll within the card if needed.
.moderation-idea-description {
  max-height: 240px;
  overflow-y: auto;

  :deep(img) {
    max-width: 100%;
    height: auto;
    border-radius: 6px;
    margin: 4px 0;
  }

  :deep(p) {
    margin: 4px 0;
  }

  :deep(ul),
  :deep(ol) {
    margin: 4px 0;
    padding-left: 24px;
  }

  :deep(ul) {
    list-style: disc;
  }

  :deep(ol) {
    list-style: decimal;
  }
}
</style>
