<template>
  <div
    class="inline-flex items-center rounded-full bg-muted"
    :class="size === 'small' ? 'gap-0.5 px-2 py-0.5' : 'gap-1 px-3 py-1'"
  >
    <button
      class="flex items-center justify-center rounded-full transition-colors hover:bg-accent disabled:opacity-40 disabled:cursor-not-allowed"
      :class="[
        userVote === 1 ? 'text-primary' : 'text-muted-foreground',
        size === 'small' ? 'size-5' : 'size-6',
      ]"
      :aria-label="$t('vote_up')"
      :disabled="disabled"
      @click.stop="$emit('vote', 'up')"
    >
      <Icon icon="mdi:chevron-up" :class="size === 'small' ? 'size-4' : 'size-5'" />
    </button>
    <span
      class="min-w-[1.25rem] text-center tabular-nums select-none"
      :class="[
        userVote !== 0 ? 'text-primary font-semibold' : 'text-foreground font-medium',
        size === 'small' ? 'text-xs' : 'text-sm',
      ]"
    >
      {{ score }}
    </span>
    <button
      class="flex items-center justify-center rounded-full transition-colors hover:bg-accent disabled:opacity-40 disabled:cursor-not-allowed"
      :class="[
        userVote === -1 ? 'text-destructive' : 'text-muted-foreground',
        size === 'small' ? 'size-5' : 'size-6',
      ]"
      :aria-label="$t('vote_down')"
      :disabled="disabled"
      @click.stop="$emit('vote', 'down')"
    >
      <Icon icon="mdi:chevron-down" :class="size === 'small' ? 'size-4' : 'size-5'" />
    </button>
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { Icon } from '@iconify/vue';
import type { VoteDirection } from 'src/types/api/ideas';

export default defineComponent({
  name: 'IdeaVoteButton',
  components: { Icon },

  props: {
    score: { type: Number, required: true },
    userVote: { type: Number as () => 1 | -1 | 0, default: 0 },
    size: { type: String as () => 'default' | 'small', default: 'default' },
    disabled: { type: Boolean, default: false },
  },

  emits: {
    vote: (direction: VoteDirection) => direction === 'up' || direction === 'down',
  },
});
</script>
